# Let me construct a 5x19 output keeping bands 0, 2, 3 and clearing band 1
# Full pattern: cols 0-4 are band 0, cols 5-9 are band 1 (should be cleared), cols 10-14 are band 2, cols 15-19 are band 3

output = [[0]*19 for _ in range(5)]

# Copy pattern to band 0 (cols 0-4)
for r in range(5):
    for c in range(5):
        output[r][c] = input_grid[r][c]

# Copy pattern to band 2 (cols 10-14)
for r in range(5):
    for c in range(10, 15):
        output[r][c] = input_grid[r][10] if c==10 else input_grid[r][10 + c-10]

# Actually let me just copy bandwidth columns properly
for r in range(5):
    for col_start, band_idx in [(0, 0), (10, 2), (15, 3)]:
        for c in range(col_start, min(col_start+5, 19)):
            output[r][c] = input_grid[r][col_start]

# Wait that doesn't work either. Let me copy properly
output = [[0]*19 for _ in range(5)]
# Band 0
for r in range(5):
    row_vals = input_grid[r][0:5]
    for c in range(5):
        output[r][c] = row_vals[c]
# Band 2
for r in range(5):
    row_vals = input_grid[r][10:15]
    for c in range(10, 15):
        output[r][c] = row_vals[c-10]
# Band 3
for r in range(5):
    row_vals = input_grid[r][15:20]  # Will be at most 4 values
    for c in range(15, 19):
        if c < len(row_vals):
            output[r][c] = row_vals[c-15]

print("Output 5x19:")
for row in output:
    print(' '.join(str(x) for x in row))

_ = print({"action": "submit", "grid": output})

# Let me try 19x19 output with bands 0, 2, 3 filled and band 1 cleared
output_19x19 = [row[:] for row in input_grid]

# Clear band 1 (cols 5-9) everywhere
for row in output_19x19:
    for col in range(5, 10):
        row[col] = 0

print("19x19 output:")
for row_idx in [0, 5, 10, 15]:
    print(f"Row {row_idx}: {' '.join(str(x) for x in output_19x19[row_idx])}")

_ = print({"action": "submit", "grid": output_19x19})

